package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.*;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.*;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import static org.assertj.core.api.Assertions.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Real app-role PostgreSQL and actual accounting source authorization, not fabricated archive payloads. */
class FinanceArchiveIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static NamedParameterJdbcTemplate named;static TransactionTemplate tx;static FinanceAccountingService accounting;static FinanceArchiveService archives;static FinanceLedgerGovernance governance;
 static final UUID T=UUID.fromString("10000000-0000-0000-0000-000000000001");UUID hotel,company,book,author,reviewer,requester,voucher;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var ds=pg.getPostgresDatabase();jdbc=new JdbcTemplate(ds);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("97").load().migrate();named=new NamedParameterJdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));var db=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var audit=new AuditWriter(named,e->{});accounting=new FinanceAccountingService(named,db,access,audit,JSON);governance=new FinanceLedgerGovernance(named,db,access,accounting);var sources=new FinanceArchiveSources(named,access,null,null,accounting,null,null,null);archives=new FinanceArchiveService(named,db,access,audit,sources);}
 @AfterAll static void stop()throws Exception{if(pg!=null)pg.close();}
 @AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){hotel=UUID.randomUUID();company=UUID.randomUUID();book=UUID.randomUUID();author=account();reviewer=account();requester=account();voucher=UUID.randomUUID();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'财务档案验收','HOTEL')",hotel,T,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'财务档案法人',?)",company,T,company.toString().replace("-",""));jdbc.update("insert into finance_store_config(tenant_id,hotel_id,company_id,manager_account_id,finance_account_id,director_account_id,leader_account_id,cashier_account_id,workflow_version,enabled) values(?,?,?,?,?,?,?,?,2,true)",T,hotel,company,author,reviewer,account(),account(),reviewer);as(author,Set.of(hotel),"*");call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"档案账套",LocalDate.of(2026,10,1))));account(new FinanceAccountingModels.Account(book,"1122","真实应收","ASSET","DEBIT","应收",false,true,-1));account(new FinanceAccountingModels.Account(book,"4001","真实权益","EQUITY","CREDIT","权益",false,true,-1));call(()->accounting.createVoucher(new FinanceAccountingModels.Voucher(voucher,book,LocalDate.of(2026,10,12),LocalDate.of(2026,10,12),"已验证财务来源",List.of(new FinanceAccountingModels.Line("1122",new BigDecimal("100.00"),BigDecimal.ZERO,"真实应收",null),new FinanceAccountingModels.Line("4001",BigDecimal.ZERO,new BigDecimal("100.00"),"真实权益",null)))));}
 @Test void sourceVersionsAndAppendOnlyNotesSurviveJsonbKeyOrderingAndNeverFollowCurrentChanges(){var original=call(()->archives.preview("VOUCHER",voucher));UUID first=UUID.randomUUID();var saved=call(()->archives.freeze(new FinanceArchiveModels.Freeze(first,"VOUCHER",voucher,original.get("sourceVersion").toString(),"原始草稿凭证档案",true)));assertThat(saved).containsEntry("id",first);assertThat(map(map(saved.get("snapshot")).get("payload"))).containsEntry("status","DRAFT");UUID note=UUID.randomUUID();call(()->archives.note(first,new FinanceArchiveModels.Note(note,"独立批注，不覆盖凭证/原件")));assertThatThrownBy(()->jdbc.update("update fac_note set body='覆盖' where id=?",note)).hasMessageContaining("append-only");assertThatThrownBy(()->jdbc.update("update fac_archive set title='覆盖' where id=?",first)).hasMessageContaining("append-only");as(reviewer,Set.of(hotel),"*");call(()->accounting.review(voucher,0));assertThatThrownBy(()->call(()->archives.freeze(new FinanceArchiveModels.Freeze(UUID.randomUUID(),"VOUCHER",voucher,original.get("sourceVersion").toString(),"伪旧版",true)))).hasMessageContaining("版本已变化");as(author,Set.of(hotel),"*");var old=call(()->archives.export(first));assertThat(map(map(old.get("snapshot")).get("payload"))).containsEntry("status","DRAFT");var latest=call(()->archives.preview("VOUCHER",voucher));call(()->archives.freeze(new FinanceArchiveModels.Freeze(UUID.randomUUID(),"VOUCHER",voucher,latest.get("sourceVersion").toString(),"独立审核后新版本",true)));assertThat(rows(call(()->archives.list("VOUCHER",voucher)).get("items"))).hasSize(2);assertThat(jdbc.queryForObject("select count(*) from fac_access where archive_id=? and action='EXPORT'",Integer.class,first)).isOne();}
 @Test void temporaryGrantRequiresIndependentReviewAndCannotBypassLiveSourceScopeOrExpiredGrant(){UUID archive=freeze();as(requester,Set.of(hotel),"finance.archive.read","finance.accounting.read");assertThat(rows(call(()->archives.list(null,null)).get("items"))).anySatisfy(r->assertThat(r).containsEntry("id",archive).containsEntry("canRead",false));assertThatThrownBy(()->call(()->archives.detail(archive))).isInstanceOf(AccessDeniedException.class);UUID request=UUID.randomUUID();call(()->archives.request(archive,new FinanceArchiveModels.Request(request,"核对财务审计原依据",1)));as(requester,Set.of(hotel),"finance.archive.read","finance.archive.grant","finance.accounting.read");assertThatThrownBy(()->call(()->archives.decide(request,new FinanceArchiveModels.Decision(0,true,"自审"),false))).hasMessageContaining("不能审核");as(reviewer,Set.of(hotel),"finance.archive.grant","finance.accounting.read");call(()->archives.decide(request,new FinanceArchiveModels.Decision(0,true,"核对用途与原来源范围"),false));as(requester,Set.of(hotel),"finance.archive.read","finance.accounting.read");assertThat(call(()->archives.detail(archive))).containsEntry("id",archive);as(requester,Set.of(UUID.randomUUID()),"finance.archive.read","finance.accounting.read");assertThatThrownBy(()->call(()->archives.detail(archive))).isInstanceOf(AccessDeniedException.class);as(requester,Set.of(hotel),"finance.archive.read");assertThatThrownBy(()->call(()->archives.detail(archive))).isInstanceOf(AccessDeniedException.class);as(reviewer,Set.of(hotel),"finance.archive.grant","finance.accounting.read");call(()->archives.decide(request,new FinanceArchiveModels.Decision(1,false,"用途结束撤销"),true));jdbc.update("insert into fac_request(id,tenant_id,archive_id,applicant_id,reason,requested_hours,status,reviewer_id,expires_at) values(?,?,?,?,'已过期授权',1,'APPROVED',?,now()-interval '1 minute')",UUID.randomUUID(),T,archive,requester,reviewer);as(requester,Set.of(hotel),"finance.archive.read","finance.accounting.read");assertThatThrownBy(()->call(()->archives.detail(archive))).hasMessageContaining("过期");}
 @Test void archiveManagersNeverGainPayrollSourceByConfigurationOrCrossTenantGrant(){jdbc.update("insert into fa_source_event(tenant_id,hotel_id,book_id,company_id,source_type,source_id,event_key,business_date,accounting_date,amount,summary,metadata,request_hash,status,voucher_id) values(?,?,?,?,'FB_PAYROLL',?,'EARNINGS:SALARY','2026-10-12','2026-10-12',100,'工资真实来源','{}',?,'DRAFT',?)",T,hotel,book,company,UUID.randomUUID(),UUID.randomUUID().toString(),voucher);UUID archive=freeze();as(reviewer,Set.of(hotel),"finance.configure","finance.accounting.read","finance.archive.read","finance.archive.grant");assertThat(rows(call(()->archives.list(null,null)).get("items"))).isEmpty();assertThatThrownBy(()->call(()->archives.detail(archive))).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->call(()->archives.request(archive,new FinanceArchiveModels.Request(UUID.randomUUID(),"配置管理员不能绕过工资权限",1)))).isInstanceOf(AccessDeniedException.class);Integer hidden=tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");jdbc.queryForObject("select set_config('app.tenant_id',?,true)",String.class,UUID.randomUUID().toString());return jdbc.queryForObject("select count(*) from fac_archive",Integer.class);});assertThat(hidden).isZero();}
 @Test void retentionNeedsIndependentPublisherAndManifestCannotClaimRestoreOrExposeUnapprovedContent(){UUID archive=freeze(),policy=UUID.randomUUID();call(()->archives.policy(new FinanceArchiveModels.Retention(policy,company,30,true,"财务确认制度版本，仅配置不删除")));assertThatThrownBy(()->call(()->archives.publishPolicy(policy))).hasMessageContaining("独立发布");as(reviewer,Set.of(hotel),"finance.archive.grant","finance.accounting.read");call(()->archives.publishPolicy(policy));assertThatThrownBy(()->jdbc.update("update fac_retention set years=1 where id=?",policy)).hasMessageContaining("immutable");as(requester,Set.of(hotel),"finance.archive.read","finance.accounting.read");var manifest=call(()->archives.manifest());assertThat(manifest).containsEntry("restoreVerified",false);assertThat(json(manifest)).doesNotContain("真实应收","已验证财务来源","snapshot\":");assertThatThrownBy(()->call(()->archives.recordOriginal(archive,UUID.randomUUID()))).isInstanceOf(AccessDeniedException.class);assertThat(call(()->archives.context())).containsEntry("automaticDeletionEnabled",false);}
 private UUID freeze(){var preview=call(()->archives.preview("VOUCHER",voucher));UUID id=UUID.randomUUID();call(()->archives.freeze(new FinanceArchiveModels.Freeze(id,"VOUCHER",voucher,preview.get("sourceVersion").toString(),"受限真实凭证档案",true)));return id;}
 private void account(FinanceAccountingModels.Account input){UUID request=UUID.randomUUID();call(()->governance.account(request,input,"档案验收真实会计科目独立发布"));as(reviewer,Set.of(hotel),"*");call(()->governance.publish(request,new FinanceControlModels.Version(0,"不同账号核实科目分类及余额方向"),false));as(author,Set.of(hotel),"*");}
 private UUID account(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'档案验收账号')",id,T,id.toString());return id;}
 private void as(UUID actor,Set<UUID> scopes,String...permissions){TenantContext.set(new TenantPrincipal(T,actor,"TEST",Set.of("TEST"),Set.of(permissions),scopes,Set.of(),false,UUID.randomUUID()));}
 private static <R> R call(Supplier<R> action){return tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");return action.get();});}
}
